import { addCollection, type IconifyJSON } from "@iconify/vue";

import libraryIcons from "./library-icons.json";

let registered = false;

/**
 * Registers the lucide icons the library's own components use (generated by
 * `pnpm --filter @muzakit/ui icons`), so they never reach the Iconify API. Called by `VIcon` on
 * first render rather than on import: importing the library must not touch global state. Icons
 * an app passes in by name are the app's to register; unregistered ones still load from the API.
 */
export const registerLibraryIcons = (): void => {
  if (registered) return;
  registered = true;
  addCollection(libraryIcons satisfies IconifyJSON);
};
